const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const SAVE_KEY='little-stone-club-v1';
let storageOK=true;
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));if(s?.version===1&&Array.isArray(s.stones)&&s.stones.every(x=>TYPES[x.id]&&Number.isFinite(x.mass)&&x.mass>0&&x.radius>0&&Array.isArray(x.genes)&&x.genes.length===4)&&Number.isFinite(s.credits)&&Number.isFinite(s.best)){s.map=clamp(s.map||0,0,4);s.discovered=s.discovered||[...new Set(s.stones.map(x=>x.id))];s.history=s.history||[];s.totalThrows=s.totalThrows||0;return s;}}catch{}return newProgress();}
const state=load();state.stones.forEach(s=>{s.outline=outlineOf(s);s.outlineGene=outlineGeneOf(s);});state.selected=state.stones.find(s=>s.uid===state.selected)?.uid||state.stones[0]?.uid||null;
let preferences=readSettings(state.sound);const audio=new GameAudio(preferences);
let mode='explore',map=MAPS[state.map],landscape=makeLandscape(map),player={x:151,y:190},target=null,loot=[],keys={},time=0,moving=false,sim=null,camera=0,charging=false,chargeTime=0,chargePower=.65,resultAt=0,resultShown=false,modalBusy=false,toastTimer,collectionFilter='all',soundFinished=false;
const canvas=$('#game'),ctx=canvas.getContext('2d'),modal=$('#modal');ctx.imageSmoothingEnabled=false;
const director=new ImpactDirector();let lastThrow=null,isReplay=false,playbackSpeed=preferences.playbackSpeed;
const followControl=mountFollow($('#followCamera'),()=>mode==='throw'&&!modal.open);
const following=followControl.active,releaseFollow=followControl.clear;
let lastObjective='distance';
