function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{if(storageOK)toast('浏览器存储不可用，本次进度暂存于内存。');storageOK=false;}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function applyPreferences(next){preferences=next;playbackSpeed=preferences.playbackSpeed;$('#playbackSpeed').value=playbackSpeed;audio.apply(preferences);state.sound=!preferences.muted;document.body.classList.toggle('reduced-motion',preferences.reducedMotion);document.body.classList.toggle('no-hints',!preferences.hints);$('#powerHint').textContent=preferences.chargeMode==='toggle'?'点击 / 空格开始蓄力，再点一次投出':'也可按住空格 · 绿色区间手感最佳';if(!writeSettings(preferences))toast('浏览器无法保存设置，本次仍然生效。');renderHeader();}
function showSettings(){openModal('把世界调成喜欢的样子','SETTINGS / TAKE YOUR TIME',settingsContent(preferences));bindSettings({get:()=>preferences,set:applyPreferences,audio,toast,rerender:showSettings,onReset:showResetProgress,onExport:exportSave});}
function toggleSound(){applyPreferences({...preferences,muted:!preferences.muted});audio.unlock().then(()=>audio.event('ui'));save();}

function renderHeader(){$('#credits').textContent=state.credits.toLocaleString();$('#bestCount').innerHTML=`${state.best}<small> 连漂</small>`;$('#mapName').textContent=map.name;$('#mapDesc').textContent=map.desc;$('#pocketCount').textContent=String(state.stones.length).padStart(2,'0');$('#collectionCount').textContent=String(state.stones.length).padStart(2,'0');$('#equippedName').textContent=equipped()?.name||'口袋空空，去捡一块吧';if(equipped())stoneIcon($('#equippedIcon'),equipped());else $('#equippedIcon').getContext('2d').clearRect(0,0,64,54);$('#soundBtn').innerHTML=!preferences.muted?'♫':'♫<span class="mute-line"></span>';$('#soundBtn').setAttribute('aria-label',preferences.muted?'开启声音':'关闭声音');$('#soundBtn').title=preferences.muted?'开启声音 (M)':'关闭声音 (M)';}
function stoneCard(s){return `<button class="stone-card ${s.uid===state.selected?'selected':''}" data-stone="${s.uid}"><span class="tag">${s.rarity}${s.level?' · +'+s.level:''}</span>${s.uid===state.selected?'<span class="check">✓</span>':''}<canvas width="84" height="65" data-icon="${s.uid}" aria-hidden="true"></canvas><strong>${s.name}</strong><p>${s.desc}</p><div class="stone-meta"><span>${Math.round(s.mass*1000)}g · ${OUTLINE_NAMES[outlineOf(s).family]}</span><b>${s.uid===state.selected?'已选中':'查看 ↗'}</b></div></button>`;}
function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(c=>{const stone=state.stones.find(s=>s.uid===c.dataset.icon);if(stone)stoneIcon(c,stone);});root.querySelectorAll('[data-stone]').forEach(b=>b.onclick=()=>showStone(b.dataset.stone));}
function renderPocket(){const order=[equipped(),...state.stones.filter(s=>s.uid!==state.selected)].filter(Boolean).slice(0,4);$('#pocketGrid').innerHTML=order.map(stoneCard).join('')+`<button class="empty-card" id="findMore"><span>＋</span>下一块，会是什么？<small>去河边碰碰运气</small></button>`;fillIcons($('#pocketGrid'));$('#findMore').onclick=()=>{setMode('explore');canvas.focus({preventScroll:true});toast('沿岸走走，靠近小石头后按 E，也可以直接点它。');};renderHeader();}
function openModal(title,eyebrow,body){releaseFollow();audio.setFlightPaused(!!sim&&!sim.done);if(charging)cancelCharge();keys={};target=null;$('#modalContent').innerHTML=`<div class="modal-head"><div><small>${eyebrow}</small><h2>${title}</h2></div><button class="close-btn" aria-label="关闭窗口">×</button></div><div class="modal-body">${body}</div>`;$('.close-btn').onclick=closeModal;if(!modal.open)modal.showModal();}
function closeModal(){if(modalBusy){toast('计算正在进行，再等一小会儿。');return;}audio.stopPreview();audio.setFlightPaused(false);modal.close();setActiveNav('shore');keys={};canvas.focus({preventScroll:true});}
modal.addEventListener('cancel',e=>{if(modalBusy)e.preventDefault();else {audio.stopPreview();audio.setFlightPaused(false);setActiveNav('shore');}});modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
function setActiveNav(id){$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===id));$('#crumb').textContent={shore:'河边散步',collection:'我的收藏',workshop:'石头改造所',atlas:'水漂手册'}[id];}
function flightBusy(){if(sim&&!sim.done){toast('这一漂还没结束，让石头再飞一会儿。');return true;}return false;}
function showMaps(){if(flightBusy())return;openModal('下一站，去哪里？','TAKE THE SCENIC ROUTE',`<p class="modal-sub">每一片水，都有自己的脾气。换个地方，也许能捡到不一样的自己。</p><div class="map-grid">${MAPS.map((m,i)=>`<button class="map-card" data-map="${i}"><canvas width="480" height="235" data-map-preview="${i}"></canvas><div><strong>${m.name} ${i===state.map?'· 当前':''}</strong><p>${m.detail}</p><small>${m.difficulty} &nbsp; · &nbsp; ${m.desc}</small></div></button>`).join('')}</div>`);$$('[data-map-preview]').forEach(c=>c.getContext('2d').drawImage(makeLandscape(MAPS[+c.dataset.mapPreview]),0,0));$$('[data-map]').forEach(b=>b.onclick=()=>{lastThrow=null;$('#replayLast').disabled=true;state.map=+b.dataset.map;map=MAPS[state.map];audio.setMap(map.id);player={x:151,y:190};sim=null;setMode('explore');spawnLoot();save();renderHeader();closeModal();toast(`抵达${map.name}。今天的石头，也很期待遇见你。`);});}
function showCollection(filter=collectionFilter){if(flightBusy())return;collectionFilter=filter;setActiveNav('collection');let list=state.stones.filter(s=>filter==='all'||(filter==='rare'?['稀有','传说','奇遇'].includes(s.rarity):s.level>0));openModal('一些石头，一些可能','POCKET UNIVERSE',`<p class="modal-sub">已收集 ${state.stones.length} 块 · 发现 ${state.discovered.length} / ${TYPES.length} 种奇物。投掷后由俱乐部回收绳取回，每一块都可以反复陪你练习。</p><div class="filter-row"><button data-filter="all" class="${filter==='all'?'active':''}">全部收藏</button><button data-filter="rare" class="${filter==='rare'?'active':''}">稀有与奇遇</button><button data-filter="modified" class="${filter==='modified'?'active':''}">改造过的</button></div><div class="stone-grid modal-grid">${list.map(stoneCard).join('')||'<p class="modal-sub">这里还空着。去河岸捡一块，或者改造一块吧。</p>'}</div><p class="save-status">${storageOK?'✓ 进度自动保存在此浏览器':'进度目前仅保留在内存中'}</p>`);fillIcons(modal);$$('[data-filter]').forEach(b=>b.onclick=()=>showCollection(b.dataset.filter));}
function showStone(uid){const s=state.stones.find(s=>s.uid===uid);if(!s||flightBusy())return;const stat=(name,value,label)=>`<div class="stat-row"><span>${name}</span><div><i style="width:${clamp(value,0,100)}%"></i></div><b>${label}</b></div>`;openModal(s.name,`${s.rarity} / NO. ${String(s.id+1).padStart(3,'0')}`,`<div class="detail-layout"><div class="detail-art"><canvas id="detailIcon" width="160" height="130"></canvas></div><div><p class="detail-desc">${s.desc}</p>${stat('平整度',s.flatness*100,Math.round(s.flatness*100)+'%')}${stat('光滑度',s.smoothness*100,Math.round(s.smoothness*100)+'%')}${stat('质量',s.mass*500,Math.round(s.mass*1000)+' g')}${stat('半径',s.radius*1500,Math.round(s.radius*1000)+' mm')}<div class="button-row"><button class="primary" id="equipStone">带它去水漂 ↗</button><button class="secondary" id="modifyStone">改造这块石头</button><button class="danger-button" id="discardStone">放回河岸…</button></div></div></div>${outlineContent(s)}${lineageContent(s)}${recordContent(s.research)}${s.quantum?`<div class="quantum-ready">已制备叠加态 · 初相位 ${s.quantum.phase}° · 初始轻薄态权重 ${Math.round(s.quantum.bias*100)}%<br>进入水漂模式可切换量子水域。飞行积累相位，碰水进行观测。</div>`:""}<div class="detail-foot">基因：${s.genes.join(' · ')} &nbsp;｜&nbsp; 个人纪录：${s.best||0} 漂 &nbsp;｜&nbsp; 加工次数：${s.level}<br>${s.history.slice(-3).join(' → ')||'天然出品，还保留着水岸的气息。'}</div>`);stoneIcon($('#detailIcon'),s);fillOutlinePreviews();$('#discardStone').onclick=()=>showDiscard(s);$('#equipStone').onclick=()=>{state.selected=s.uid;save();renderPocket();closeModal();setMode('throw');toast('稍微向下出手，石片保持约 20°。按住按钮蓄力，松手就漂。');};$('#modifyStone').onclick=()=>{state.selected=s.uid;save();renderPocket();showWorkshops();};}
function showWorkshops(){if(flightBusy())return;if(!equipped()){toast('研究对象溜去河边了，先捡一块石头吧。');setMode('explore');return;}setActiveNav('workshop');openModal('让石头，有点不一样','THE VERY SERIOUS STONE INSTITUTE',`<p class="modal-sub">当前研究对象：<b>${equipped().name}</b> &nbsp; · &nbsp; 可用灵感 ✦ ${state.credits}<br>从一把锤子到整个宇宙，你离好石头只差一点点离谱。</p><div class="workshop-grid">${FACILITIES.map(f=>`<button class="workshop-card" data-facility="${f.id}"><span class="facility-icon">${f.icon}</span><div><h3>${f.name}</h3><p>${f.desc}</p><small>${f.tag} &nbsp; · &nbsp; ${f.cost?'✦ '+f.cost:'免费，风险自担'}</small></div></button>`).join('')}</div><div class="button-row"><button class="secondary" id="workshopSelect">更换研究对象</button></div>`);$$('[data-facility]').forEach(b=>b.onclick=()=>showFacility(b.dataset.facility));$('#workshopSelect').onclick=()=>showCollection();}
function showFacility(id){const f=FACILITIES.find(x=>x.id===id),s=equipped();if(!s)return showWorkshops();let controls='';const range=(id,label,min,max,value,step=1)=>`<label>${label} <output id="${id}Out">${value}</output><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}"></label>`;
 if(id==='smash')controls='<p class="modal-sub">随机敲掉一小段轮廓，改变质量、平整度和光滑度。下手越多，不一定越好；无论结果如何，这块石头仍然属于你。师傅先试几种落锤位置，按目标选用；不保证超过原石。</p>';
 if(id==='home')controls='<p class="modal-sub">试磨几种砂纸与边缘处理，再按目标选择一种。适合一块值得慢慢打磨的石头。</p>';
 if(id==='factory')controls=`<div class="science-controls">${range('mill','保留质量（%）',50,95,75)}${range('radius','保留半径（%）',70,100,95)}<label>轮廓切削模板<select id="cutShape">${['round','oval','triangle','square','leaf'].map(k=>`<option value="${k}">${OUTLINE_NAMES[k]}</option>`).join('')}</select></label><small>只切掉原轮廓之外的材料，缺口与孔洞不会被填平。</small><small>精加工只去除材料。平整度至少 96%，光滑度至少 95%。</small></div>`;
 if(id==='fluid')controls='<div class="science-controls"><p class="modal-sub">以 13 m/s 的出手速度，联合测试 7 档出手角（−20°—15°）、8 档倾角（8°—36°）与 7 档旋转（0—70 r/s），共 392 组组合。按所选目标排名，相同成绩再比另一项；同时保留当前姿态作为对照。</p><small>这项研究调整投掷建议，不会凭空改变材料。</small></div>';
 if(id==='quantum')controls=`<div class="science-controls">${range('quantumBias','初始轻薄态权重（%）',10,90,Math.round((s.quantum?.bias??.5)*100))}${range('quantumPhase','初始相位（°）',0,360,s.quantum?.phase??0,15)}<small>石头与水均有相位。飞行积累相位，每次接触水面都观测并坍缩；相对相位决定 + / − 通道的概率，通道改变本次接触的升阻力。彩色水线、轨迹与相位罗盘对应同一相位色环。以你设定的权重、相位为中心微调，对每个候选用相同五组种子试漂，再按平均成绩选优。</small></div>`;
 if(id==='bio')controls=nurseryForm(s,state.stones);
 if(id==='time')controls=`<div class="science-controls"><label>选择最初的形成环境<select id="formation"><option value="sediment">远古河床 · 层层沉积（更薄、更平）</option><option value="volcano">火山熔岩 · 急速冷却（更轻、更粗）</option><option value="pressure">地壳深处 · 高压变质（更密、更光滑）</option></select></label>${range('era','干预强度（%）',10,100,70)}<small>历史只改写这块石头。你今天吃过的午饭暂时安全。</small></div>`;
 if(id==='future')controls='<div class="science-controls"><p class="modal-sub">192 个候选：8 档质量 × 6 档半径 × 4 档层理。使用两个 Web Worker 并行运行相同的水漂物理模拟，分别记录距离和次数，按选定目标挑选。</p><small>筛选条件：静水、13 m/s、出手 −8°、倾角 20°、旋转 35 r/s。最佳解只针对这个有限参数网格。</small></div>';
 openModal(f.name,f.tag,`<p class="modal-sub">研究对象 <b>${s.name}</b> · 预算 <strong id="quote">✦ ${f.cost} / 现有 ${state.credits}</strong></p>${workshopMarkup(id)}<div id="facilityInputs">${objectiveControl(lastObjective)}${controls}<p id="budgetNote" class="farewell-note"></p></div><div id="processStatus"></div><div class="button-row" id="workButtons"><button class="primary" id="applyFacility">开始${id==='fluid'?'水槽试验':id==='future'?'并行筛选':'改造'} ↗</button><button class="secondary" id="backFacility">返回改造所</button></div>`);
 $$('.science-controls input[type=range]').forEach(i=>i.oninput=()=>$('#'+i.id+'Out').textContent=i.value);
 for(const el of $$('[name=objective]'))el.addEventListener('change',()=>lastObjective=el.value);
 if(id==='bio')bindNursery(s,state.stones,state.credits);
 else $('#budgetNote').textContent='比较候选的实际试漂成绩。目标并列时，用另一项成绩决定；结果页会列出原方案作对照。';
 $('#backFacility').onclick=showWorkshops;$('#applyFacility').onclick=()=>applyFacility(f,s);
}
const trialScores=r=>`${Number(r.distance.toFixed(1))} m · ${Number(r.skips.toFixed(1))} 漂`;
async function applyFacility(f,s){
 if(modalBusy)return;
 const bio=f.id==='bio',objective=$('[name=objective]:checked').value,plan=bio?readPlan(s,state.stones):null;
 const cost=bio?plan.cost:f.cost;if(cost===null||state.credits<cost){toast('请选择足够的亲本，并检查灵感预算。');return;}
 const options={};for(const id of ['mill','radius','cutShape','formation','era','quantumBias','quantumPhase']){const el=$('#'+id);if(el)options[id]=el.type==='range'?Number(el.value):el.value;}
 const params={pitch:+$('#pitch').value,tilt:+$('#tilt').value,spin:+$('#spin').value};
 modalBusy=true;audio.event(f.id);for(const el of $$('#facilityInputs input,#facilityInputs select,#workButtons button'))el.disabled=true;
 let changed,message,extra;
 try{
  await processStage(f.id,0);
  if(bio){
   changed=await runNursery(plan,{reducedMotion:()=>preferences.reducedMotion,sound:event=>audio.event(event)});
   message=plan.mode==='program'?`委托完成！${plan.rounds} 代试漂，今天由「${changed.name}」带成绩回家。`:`「${changed.name}」从这一窝的六块石头中入选。`;
   extra=recordContent(changed.research)+lineageContent(changed);
  }else{
   await processStage(f.id,1);
   $('#processStatus').innerHTML='<p id="computeLabel" class="modal-sub" role="status">研究员正在试漂候选方案…</p><div class="loading-bar"><i id="computeProgress" style="width:0"></i></div>';
   const best=await searchFacility(f.id,s,objective,{params,options,onProgress:p=>{$('#computeProgress').style.width=p*100+'%';$('#computeLabel').textContent='研究员正在试漂候选方案… '+Math.round(p*100)+'%';}});
   changed={...(best.stone||s),history:[...s.history]};
   if(f.id==='fluid'){changed.recommendedThrow={...best.params};changed.recommendedTilt=best.params.tilt;applyThrowSettings(best.params);}
   else if(f.id!=='quantum'){delete changed.recommendedThrow;delete changed.recommendedTilt;}
   message=f.id==='fluid'?`建议出手 ${best.params.pitch}° · 倾角 ${best.params.tilt}° · 自旋 ${best.params.spin} r/s`:f.id==='quantum'?`叠加态制备完成：相位 ${changed.quantum.phase}°，轻薄态权重 ${Math.round(changed.quantum.bias*100)}%。`:`研究员采用了「${best.recipe}」。`;
   extra=`<div class="study-ledger"><b>${GOAL_NAMES[objective]} · 比较了 ${best.count} 种方案</b><small>${best.conditions}</small><ol><li><span>原方案</span><strong>${trialScores(best.baseline)}</strong></li><li><span>入选方案</span><strong>${trialScores(best.result)}</strong></li></ol></div>`;
   await processStage(f.id,2);
  }
 }catch(e){modalBusy=false;toast(e.message||'改造未完成，灵感已保留。');showFacility(f.id);return;}
 changed.level=(changed.level||0)+1;changed.history=[...(changed.history||[]),f.name].slice(-100);
 if(bio){state.stones.push(changed);state.selected=changed.uid;}else state.stones[state.stones.findIndex(x=>x.uid===s.uid)]=changed;
 state.credits-=cost;save();renderPocket();modalBusy=false;audio.event('craft');
 openModal(bio?'这一窝，谁最会漂？':'石头，焕然一新',bio?'FIELD NOTES / BREEDING STATION':'A SMALL CHANGE, A NEW POSSIBILITY',`<div class="result-center"><canvas id="modifiedIcon" width="168" height="100" style="image-rendering:pixelated"></canvas><p class="result-comment">${message}</p><div class="result-stats"><div><b>${Math.round(changed.mass*1000)}g</b><span>原 ${Math.round(s.mass*1000)}g</span></div><div><b>${Math.round(changed.flatness*100)}%</b><span>平整度 · 原 ${Math.round(s.flatness*100)}%</span></div><div><b>${Math.round(changed.smoothness*100)}%</b><span>光滑度 · 原 ${Math.round(s.smoothness*100)}%</span></div></div>${outlineContent(changed)}${extra}<div class="button-row"><button class="primary" id="testModified">带它试一漂 ↗</button><button class="secondary" id="moreModify">继续改造</button></div></div>`);
 stoneIcon($('#modifiedIcon'),changed);fillOutlinePreviews();$('#testModified').onclick=()=>{closeModal();setMode('throw');};$('#moreModify').onclick=showWorkshops;
}
function showManual(physics=false){setActiveNav('atlas');openModal(physics?'这片水，真的有点物理':'河边生活使用说明','A FIELD GUIDE TO LITTLE JOYS',`<div class="physics-text">${physics?`<p>不是预设弹跳动画。每一帧都在计算石头的运动，水面会响应冲击。为了浏览器实时运行，使用降阶模型，不能当作工程 CFD 或真实材料设计软件。</p><h3>01 / 一维水面</h3><p>512 个网格、网格间距 0.35 m、水深 1.2 m。求解线性化浅水方程，交错网格更新水位与水平速度，边缘有吸收层。</p><code>∂η/∂t = −H ∂u/∂x　 ·　 ∂u/∂t = −g ∂η/∂x − γu</code><p>固定时间步 1/240 s，满足波动传播的 CFL 稳定性条件。波浪改变局部水面高度、坡度与相对入水速度。该近似适用于小振幅长波；没有解析湍流、破波与完整三维溅射。</p><h3>02 / 石头与水</h3><code>升力 L = ½ρv²A湿 CL　 ·　 阻力 D = ½ρv²A湿 CD</code><p>用 32 点实际轮廓，按自旋转动边界，再与水面半平面裁剪，积分浸水面积与面积重心。轮廓的圆度、孔洞和转动惯量参与升阻力、浮力与旋转稳定性估算；仍未求解完整三维姿态动力学。接触阶段以 1/960 s 子步积分升力、阻力、重力与近似浮力；石头离水向上运动时才记一次成功弹跳。加入空气阻力、自旋衰减与姿态摆动，反弹离水速度受入水动能约束。</p><p>质量、半径、轮廓形状、平整度、光滑度、入射角与石片倾角都会影响结果。升阻力系数、摆动和材质映射包含游戏校准；基因、量子态和时间干预属于科幻玩法。画面会夸大竖直位移方便观察。</p><h3>03 / 20° 的小秘密</h3><p>研究发现，约 20° 的石片与水面夹角能在多种投掷条件下改善弹跳表现；它不是出手速度与水平线的夹角，也不保证所有形状都最优。</p><p>参考：<a href="https://www.nature.com/articles/427029a" target="_blank" rel="noopener">Clanet, Hersen & Bocquet (2004), Nature</a>；<a href="https://arxiv.org/abs/physics/0210015" target="_blank" rel="noopener">Bocquet, The physics of stone skipping</a>。</p>`:`<h3>01 / 先当一个快乐的捡石人</h3><p>WASD / 方向键在浅滩行走，靠近石头按 E 拾取。也可以点击地面走过去，点击石头自动靠近并拾取。会说话的石头 NPC 有自己的意见，聊完天、得到它的同意后也能一起旅行。</p><h3>02 / 亲手打一个水漂</h3><p>选择口袋里的石头，进入水漂模式。建议出手角度 −8°、石片倾角 20°、旋转 35 r/s 起步。按住投掷按钮或空格蓄力，松开投出；蓄力会来回摆动，绿色提示区间比较稳。点击一次也能轻轻投出。</p><p>投掷面板可选 0.5×、0.25×、0.1× 慢放，水花音效也同步拉长、降调。长按 F 或「镜头跟随」按钮可随石头飞行，接水时拉近慢放；松开即恢复全景与所选速度；结算后可以慢放回看，不重复发放奖励。</p><p>投掷后使用俱乐部回收绳取回石头。每次至少获得 8 点灵感，多漂、多远都有额外奖励。</p><h3>03 / 从砂纸到宇宙</h3><p>改造所里有 8 条路线。砸石免费但随机；打磨稳定改善表面；工厂可精确减材；流体实验室联合优化出手角、倾角和旋转；量子平台制备叠加态，进入量子水域后飞行积累相位、碰水观测；泛生物研究所支持 2–6 亲本杂交、质感遗传、轮廓拼接和逐代委托育种；时间公司改变形成历史；未来材料实验室实际并行模拟 192 个候选。八条路线都可选距离或次数优先，同分再看另一项。育种每代试漂六块，同条件择优、保留历代最佳。</p><h3>04 / 今天，什么都可以是石头</h3><p>5 张地图、24 种奇物，包括吐司、ESC 键帽、软盘、CPU、鸭子和愿意同行的 NPC。进度自动保存到当前浏览器；不同浏览器之间不会自动同步。</p><div class="achievement">已发现 ${state.discovered.length} / ${TYPES.length} 种 · 已投掷 ${state.totalThrows} 次 · 最佳 ${state.best} 漂 / ${state.bestDistance||0} m</div><div class="button-row"><button class="secondary" id="manualPhysics">看看水漂物理 ↗</button><button class="secondary" id="exportSave">导出我的收藏备份</button><button class="secondary" id="importSave">导入收藏备份</button><input id="saveFile" type="file" accept="application/json,.json" hidden></div>`}</div>`);if(!physics){$('#manualPhysics').onclick=()=>showManual(true);$('#exportSave').onclick=exportSave;$('#importSave').onclick=()=>$('#saveFile').click();$('#saveFile').onchange=importSave;}}
function exportSave(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='小石头俱乐部-收藏备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('收藏已打包，换台设备也能继续散步。');}
async function importSave(e){try{const file=e.target.files[0];if(!file)return;if(file.size>12e6)throw new Error();const s=JSON.parse(await file.text());if(s.version!==1||!Array.isArray(s.stones)||s.stones.length>2000||!Number.isFinite(s.credits)||s.credits<0||!Number.isFinite(s.best))throw new Error();const clean=s.stones.map(x=>{if(!TYPES[x.id]||!Number.isFinite(x.mass)||x.mass<.008||x.mass>.3||!Number.isFinite(x.radius)||x.radius<.014||x.radius>.07||!Number.isFinite(x.flatness)||x.flatness<0||x.flatness>1||!Number.isFinite(x.smoothness)||x.smoothness<0||x.smoothness>1||!Array.isArray(x.genes)||x.genes.length!==4||!x.genes.every(b=>BASES.includes(b)))throw new Error();const out={...makeStone(x.id,false),mass:x.mass,radius:x.radius,flatness:x.flatness,smoothness:x.smoothness,thickness:clamp(Number(x.thickness)||.01,.003,.03),genes:x.genes,level:clamp(Number(x.level)||0,0,9999),best:clamp(Number(x.best)||0,0,9999)};out.history=Array.isArray(x.history)?x.history.filter(h=>FACILITIES.some(f=>f.name===h)).slice(-100):[];if(x.name===TYPES[x.id].name+'·混血')out.name=x.name;return restoreRecord(restoreResearch(out,x),x);});lastThrow=null;$('#replayLast').disabled=true;state.stones=clean;state.selected=clean[s.stones.findIndex(x=>x.uid===s.selected)]?.uid||clean[0]?.uid||null;state.credits=Math.floor(clamp(s.credits,0,1e9));state.best=Math.floor(clamp(s.best,0,9999));state.bestDistance=clamp(Number(s.bestDistance)||0,0,10000);state.totalThrows=clamp(Number(s.totalThrows)||0,0,1e8);state.discovered=[...new Set([...(Array.isArray(s.discovered)?s.discovered.filter(id=>Number.isInteger(id)&&TYPES[id]):[]),...clean.map(x=>x.id)])];state.history=[];state.map=clamp(Math.floor(Number(s.map)||0),0,4);map=MAPS[state.map];sim=null;resultShown=true;player={x:151,y:190};audio.setMap(map.id);audio.setFlight(false);spawnLoot();setMode('explore');save();renderPocket();showCollection();toast('收藏备份已导入。老朋友们都到了。');}catch{toast('这份备份格式不正确，现有收藏未改变。');}}
function spawnLoot(){loot=[];const random=rng(989+state.map*67+state.stones.length*71);for(let i=0;i<10;i++){loot.push({id:map.loot[Math.floor(random()*map.loot.length)],x:65+random()*353,y:178+random()*33,phase:random()*6,uid:i});}loot[0]={...loot[0],x:169,y:184,id:map.loot[0]};loot[1]={...loot[1],x:124,y:197,id:map.loot[1]};}
function nearest(){let best=null,dist=24;for(const l of loot){const d=Math.hypot(l.x-player.x,(l.y-player.y)*1.4);if(d<dist){dist=d;best={...l,type:'stone'};}}const d=Math.hypot(285-player.x,(190-player.y)*1.4);if(d<dist)best={type:'npc',x:285,y:190};return best;}
function pickUp(){if(mode!=='explore'||modal.open)return;const n=nearest();if(!n){toast('靠近地上的闪光石头再捡。点击石头也可以走过去。');return;}if(n.type==='npc'){talkNPC();return;}const s=makeStone(n.id);state.stones.push(s);if(!state.discovered.includes(s.id))state.discovered.push(s.id);state.credits+=6;loot=loot.filter(l=>l.uid!==n.uid);state.selected=s.uid;save();renderPocket();audio.event('pickup');toast(`捡到了「${s.name}」！灵感 +6 ✦`);if(loot.length<4){const currentMap=state.map;setTimeout(()=>{if(currentMap===state.map)spawnLoot();},8000);}}
function talkNPC(){audio.event('npc');const already=state.stones.some(s=>s.id===map.npcStone);openModal(map.npc,'SOME STONES HAVE STORIES',`<div class="result-center"><canvas id="npcPortrait" width="150" height="100" style="image-rendering:pixelated"></canvas><p class="result-comment">“${map.line}”</p><p class="modal-sub">${already?'谢谢你带另一个我出去看世界。石头嘛，分身多一点很正常。':'如果你愿意，我也想去别的水岸看看。你可以带我走，偶尔打个水漂也没关系，我会游泳。'}</p><div class="button-row" style="justify-content:center"><button class="primary" id="inviteNpc">${already?'再聊一句':'邀请它加入收藏'} ↗</button><button class="secondary" id="leaveNpc">一起发会儿呆</button></div></div>`);stoneIcon($('#npcPortrait'),TYPES[map.npcStone]);$('#leaveNpc').onclick=closeModal;$('#inviteNpc').onclick=()=>{if(already){toast('“你知道吗？石头也有梦想。我的梦想是再睡五分钟。”');closeModal();return;}const s=makeStone(map.npcStone,false);state.stones.push(s);state.discovered.push(s.id);state.selected=s.uid;state.credits+=15;save();renderPocket();closeModal();toast(`${map.npc}加入了收藏。它看上去有一点点期待。灵感 +15 ✦`);};}
function setMode(next){if(flightBusy())return;if(next==='throw'&&!equipped()){toast('先去浅滩捡一块石头，再来试手气。');next='explore';}releaseFollow();if(charging)cancelCharge();mode=next;director.reset();isReplay=false;playbackSpeed=preferences.playbackSpeed;$('#playbackSpeed').value=playbackSpeed;audio.setFlight(false);sim=null;camera=0;target=null;landscape=makeLandscape(map,next);$('#exploreBtn').classList.toggle('active',next==='explore');$('#skipModeBtn').classList.toggle('active',next==='throw');$('#exploreHelp').classList.toggle('hidden',next!=='explore');$('#throwPanel').classList.toggle('hidden',next!=='throw');$('#cinemaControls').classList.toggle('hidden',next!=='throw');$('#cinemaReadout').textContent='按住 F 或镜头按钮跟随，松开回到全景。';$('#flightHud').classList.add('hidden');$('#quantumTelemetry').classList.add('hidden');$('#sceneMood').textContent=next==='explore'?'慢慢走，好石头不怕等。':'让手腕轻一点，让石头飞远一点。';$('#throwBtn').disabled=false;$('#throwText').textContent=preferences.chargeMode==='toggle'?'点击蓄力，再点出发 ↗':'按住蓄力，松手出发 ↗';$('#chargeFill').style.width='0';renderHeader();$('#quantumControl').classList.toggle('hidden',!equipped()?.quantum);$('#quantumMode').checked=!!equipped()?.quantum;if(next==='throw'){if(equipped().recommendedThrow)applyThrowSettings(equipped().recommendedThrow);else if(equipped().recommendedTilt)applyThrowSettings({pitch:-8,tilt:equipped().recommendedTilt,spin:35});}}
function startCharge(e){if(e?.button!==undefined&&e.button!==0)return;if(!equipped()||mode!=='throw'||(sim&&!sim.done)||modal.open||charging)return;e?.preventDefault();charging=true;chargeTime=0;chargePower=.38;sim=null;resultShown=true;audio.event('charge');}
function cancelCharge(){charging=false;chargeTime=0;$('#chargeFill').style.width='0';$('#throwText').textContent=preferences.chargeMode==='toggle'?'点击蓄力，再点出发 ↗':'按住蓄力，松手出发 ↗';}
function releaseCharge(){if(!charging)return;charging=false;lastThrow={stone:structuredClone(equipped()),params:{speed:5+chargePower*12,pitch:+$('#pitch').value,tilt:+$('#tilt').value,spin:+$('#spin').value},environment:{...map},quantum:$('#quantumMode').checked&&!!equipped().quantum,seed:Math.floor(Math.random()*4294967296)};beginThrow(lastThrow,false);}
function finishThrow(){
 if(resultShown||!sim?.done)return;resultShown=true;const result=sim.result(),{reward,isRecord}=settleThrow(state,result,sim.stone.uid,map.name,isReplay);
 audio.setFlight(false);if(isRecord)audio.event('record');if(!isReplay){save();renderPocket();}
 $('#throwBtn').disabled=false;$('#replayLast').disabled=false;
 openModal(isReplay?'慢一点，再看一次水花':isRecord?'这一次，漂得漂亮！':result.skips?'又一个轻盈的下午':'扑通，也是一种快乐',isReplay?'SLOW MOTION / SAME LITTLE MOMENT':'A LITTLE THROW, A LITTLE JOY',`<div class="result-center"><div class="result-big">${String(result.skips).padStart(2,'0')}<small>连漂</small></div><p class="result-comment">${isReplay?'同一块石头、同一掷法、同一量子观测。回放不改写进度。':isRecord?'新纪录！这块石头，值得一个小小的庆祝。':result.reason}</p><div class="result-stats"><div><b>${result.distance}<small> m</small></b><span>漂行距离</span></div><div><b>${result.duration}<small> s</small></b><span>物理世界中的时长</span></div><div><b>${isReplay?'回放':'+'+reward+' ✦'}</b><span>${isReplay?'不重复获得奖励':'获得灵感'}</span></div></div>${sim instanceof QuantumSkipSimulation?quantumResult(sim):''}<p class="modal-sub">${sim.contacts.length} 次接触 · ${OUTLINE_NAMES[outlineOf(sim.stone).family]} · 俱乐部已取回「${sim.stone.name}」。<br>回放时按住 F 或镜头按钮，看看它最后一次碰水。</p><div class="button-row" style="justify-content:center"><button class="primary" id="again">再漂一次 ↗</button><button class="secondary" id="replayThrow">慢放回看 ↗</button><button class="secondary" id="resultWorkshop">去改造一下</button><button class="secondary" id="backWalk">回岸边散步</button></div></div>`);
 $('#again').onclick=()=>{closeModal();setMode('throw');};$('#replayThrow').onclick=replayLastThrow;$('#resultWorkshop').onclick=showWorkshops;$('#backWalk').onclick=()=>{closeModal();setMode('explore');};
}
function canvasPoint(e){const b=canvas.getBoundingClientRect(),scale=Math.max(b.width/960,b.height/470);const visibleWidth=b.width/scale,visibleHeight=b.height/scale;const offsetX=(960-visibleWidth)*(innerWidth<=540?.44:.5),offsetY=(470-visibleHeight)*.5;return {x:((e.clientX-b.left)/scale+offsetX)/2,y:((e.clientY-b.top)/scale+offsetY)/2};}
canvas.addEventListener('pointerdown',e=>{if(mode!=='explore'||modal.open)return;const p=canvasPoint(e);let clicked=loot.find(s=>Math.hypot(s.x-p.x,s.y-p.y)<11);if(Math.hypot(p.x-285,p.y-187)<14)target={x:285,y:190,type:'npc'};else if(clicked)target={x:clicked.x,y:clicked.y,type:'stone',uid:clicked.uid};else target={x:clamp(p.x,38,447),y:clamp(p.y,176,215)};canvas.focus({preventScroll:true});});
$('#throwBtn').addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button===0){$('#throwBtn').setPointerCapture(e.pointerId);if(preferences.chargeMode==='toggle'&&charging)releaseCharge();else startCharge(e);}});$('#throwBtn').addEventListener('pointerup',()=>{if(preferences.chargeMode==='hold')releaseCharge();});$('#throwBtn').addEventListener('pointercancel',cancelCharge);window.addEventListener('blur',()=>{keys={};cancelCharge();});document.addEventListener('visibilitychange',()=>{audio.setHidden(document.hidden);audio.setFlightPaused(!!sim&&!sim.done&&(document.hidden||modal.open));if(document.hidden){keys={};cancelCharge();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.open){e.preventDefault();showSettings();return;}if(e.key.toLowerCase()==='m'&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){if(!e.repeat)toggleSound();return;}if(e.defaultPrevented||modal.open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'&&!e.repeat)pickUp();if(k===' '&&!e.repeat){if(preferences.chargeMode==='toggle'&&charging)releaseCharge();else startCharge();}});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key===' '&&preferences.chargeMode==='hold')releaseCharge();});
$('#mapBtn').onclick=showMaps;$('#sideMap').onclick=showMaps;$('#exploreBtn').onclick=()=>setMode('explore');$('#skipModeBtn').onclick=()=>setMode('throw');$('#pickupBtn').onclick=pickUp;$('#allStones').onclick=()=>showCollection();$('#changeStone').onclick=()=>showCollection();$('#physicsBtn').onclick=()=>showManual(true);$('#soundBtn').onclick=toggleSound;$('#settingsBtn').onclick=showSettings;$('#wallet').onclick=()=>toast('灵感来自每一次发现：捡石 +6，邀请 NPC +15，投掷至少 +8。');$$('[data-nav]').forEach(b=>b.onclick=()=>{if(flightBusy())return;({shore:()=>{setActiveNav('shore');setMode('explore');},collection:()=>showCollection(),workshop:showWorkshops,atlas:()=>showManual()})[b.dataset.nav]();});['pitch','tilt','spin'].forEach(id=>$('#'+id).oninput=()=>$('#'+id+'Value').textContent=$('#'+id).value+(id==='spin'?' r/s':'°'));
function update(dt){audio.setFlightPaused(!!sim&&!sim.done&&(modal.open||document.hidden));time+=dt;moving=false;if(mode==='explore'&&!modal.open){let dx=0,dy=0;if(keys.a||keys.arrowleft)dx--;if(keys.d||keys.arrowright)dx++;if(keys.w||keys.arrowup)dy--;if(keys.s||keys.arrowdown)dy++;if(dx||dy)target=null;if(target){const vx=target.x-player.x,vy=target.y-player.y,d=Math.hypot(vx,vy);if(d<2){const action=target.type;target=null;if(action==='stone')pickUp();else if(action==='npc')talkNPC();}else{dx=vx/d;dy=vy/d;}}if(dx||dy){const n=Math.max(1,Math.hypot(dx,dy));player.x=clamp(player.x+dx/n*44*dt,38,447);player.y=clamp(player.y+dy/n*36*dt,176,215);moving=true;audio.step(time);}const near=nearest();const nextPickup=near?.type==='npc'?`<span>☏</span> 和${map.npc}聊聊 <kbd>E</kbd>`:'<span>✧</span> 捡起附近的石头 <kbd>E</kbd>';if($('#pickupBtn').innerHTML!==nextPickup)$('#pickupBtn').innerHTML=nextPickup;}
 if(charging){chargeTime+=dt;chargePower=.38+.6*(.5-.5*Math.cos(chargeTime*2.8));$('#chargeFill').style.width=(chargePower*100)+'%';const good=chargePower>.76&&chargePower<.95;$('#chargeFill').style.background=good?'#8daa65':'#cc9a59';$('#throwText').textContent=`${Math.round(chargePower*100)}% · ${preferences.chargeMode==='toggle'?(good?'就是现在，再点一次！':'再点一次投出 ↗'):(good?'就是现在，松手！':'松手投出 ↗')}`;}
 if(sim&&!modal.open){renderQuantumTelemetry();director.updateView(sim,dt,{follow:following(),reducedMotion:preferences.reducedMotion});$('#cinemaReadout').textContent=(isReplay?'回放 · ':'')+director.rate.toFixed(2)+'× · '+(following()&&director.isClose(sim)?(sim.contact?'接水特写 #':'碰水特写 #')+(sim.contacts.length||1):following()?'镜头跟随中':'全景飞行')+' · 音效同步慢放';if(!sim.done){director.advance(sim,dt,{speed:playbackSpeed,follow:following()},rate=>audio.setTimeScale(rate));camera=Math.max(0,sim.x-29);$('#liveSkips').textContent=String(sim.skips).padStart(2,'0');$('#liveDistance').innerHTML=(sim.x-1.5).toFixed(1)+'<em>m</em>';$('#liveSpeed').innerHTML=Math.hypot(sim.vx,sim.vy).toFixed(1)+'<em>m/s</em>';}else if(!resultShown){if(!soundFinished){audio.event('sink');soundFinished=true;}resultAt+=dt;if(resultAt>1)finishThrow();}}
}
function draw(){ctx.setTransform(2,0,0,2,0,0);ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,480,235);ctx.save();if(mode==='throw'&&sim&&director.zoom>1){const z=director.zoom,fx=53+(sim.x-camera)*11,fy=172-Math.max(0,sim.y)*24;ctx.translate(clamp(240-fx*z,480*(1-z),0),clamp(140-fy*z,235*(1-z),0));ctx.scale(z,z);}ctx.drawImage(landscape,0,0);ambient(ctx,preferences.reducedMotion?0:time,map,mode);if(mode==='explore'){const near=nearest();for(const l of loot){drawStone(ctx,TYPES[l.id],l.x,l.y,.38);if(!preferences.reducedMotion&&Math.sin(time*2+l.phase)>.6){ctx.fillStyle='#f3ecb9';ctx.fillRect(l.x+6,l.y-6,1,5);ctx.fillRect(l.x+4,l.y-4,5,1);}if(near?.type==='stone'&&near.uid===l.uid){ctx.strokeStyle='#e9ecc5';ctx.lineWidth=1;ctx.strokeRect(Math.round(l.x-9),Math.round(l.y-7),18,12);}}
 const entities=[{y:player.y,draw:()=>drawPlayer(ctx,player.x,player.y,time,moving)},{y:190,draw:()=>{drawStone(ctx,TYPES[map.npcStone],285,190,.7,true);ctx.fillStyle='#f0efcf';ctx.fillRect(279,168,12,10);ctx.fillStyle='#6f8264';ctx.font='bold 7px monospace';ctx.fillText('···',279,174);ctx.fillStyle='#f0efcf';ctx.fillRect(282,178,3,2);}}];entities.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());ctx.font='6px "Noto Sans SC",sans-serif';ctx.textAlign='center';ctx.fillStyle='#f4f2d6';ctx.shadowColor='#486746';ctx.shadowBlur=2;ctx.fillText('你',player.x,player.y+12);ctx.shadowBlur=0;ctx.textAlign='left';
 }else{drawPlayer(ctx,37,201,time,false,charging||!!sim);const baseline=172,scaleX=11,scaleY=24;ctx.strokeStyle='#d4e4bf';ctx.lineWidth=1;ctx.beginPath();for(let px=53;px<480;px+=2){const h=sim?sim.water.sample(camera+(px-53)/scaleX).height:Math.sin(px*.06+time)*map.wave;const y=baseline-h*scaleY;px===53?ctx.moveTo(px,y):ctx.lineTo(px,y);}ctx.stroke();ctx.font='5px monospace';for(let x=Math.ceil(camera/10)*10;x<camera+42;x+=10){const px=53+(x-camera)*scaleX;if(px<52)continue;ctx.fillStyle='#d4e3c088';ctx.fillRect(px,179,1,3);ctx.fillStyle='#d6e6c9';ctx.fillText(x+'m',px-3,190);}
 if(sim){ctx.strokeStyle=preferences.trajectory?'#f6e6b4aa':'transparent';ctx.setLineDash([2,3]);ctx.beginPath();sim.trail.forEach((p,i)=>{const x=53+(p.x-camera)*scaleX,y=baseline-p.y*scaleY;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.stroke();ctx.setLineDash([]);for(const [i,contact]of sim.contacts.entries()){const age=sim.time-contact.time,x=53+(contact.x-camera)*scaleX;if(x<45||x>490)continue;ctx.strokeStyle=`rgba(239,244,209,${Math.max(.1,1-age*.55)})`;ctx.beginPath();ctx.ellipse(x,baseline,4+Math.min(age,2)*9,1.5+Math.min(age,2)*2,0,0,Math.PI*2);ctx.stroke();if(contact.success){ctx.fillStyle='#f1edc9';ctx.font='7px monospace';ctx.fillText(String(i+1),x-1,baseline-10);}if(age<.5){for(let j=0;j<5;j++){const xx=x+(j-2)*age*15,yy=baseline-Math.sin(age/.5*Math.PI)*(5+j%3*3);ctx.fillStyle='#e8f0d0';ctx.fillRect(xx,yy,1,2);}}}if(!sim.done){const x=53+(sim.x-camera)*scaleX,y=baseline-sim.y*scaleY;ctx.save();ctx.translate(x,y);ctx.rotate(-sim.tilt);drawOutline(ctx,sim.stone,0,0,4.2,sim.rotation,.4+Math.sin(sim.tilt)*.5);ctx.restore();}if(sim instanceof QuantumSkipSimulation)drawQuantum(ctx,sim,camera,sim.stone,drawStone,{...preferences,compact:canvas.clientWidth<540||director.zoom>1.1});}
 else{const power=charging?chargePower:.6,speed=5+power*12,angle=+$('#pitch').value*Math.PI/180;ctx.fillStyle='#f9efc3aa';for(let t=0;preferences.trajectory&&t<.45;t+=.055){const x=70+speed*Math.cos(angle)*t*scaleX,y=baseline-(.48+speed*Math.sin(angle)*t-4.905*t*t)*scaleY;if(y>baseline)break;ctx.fillRect(x,y,1,1);}drawStone(ctx,equipped(),46,185,.35);}}
 ctx.restore();if(mode==='throw'&&following())drawImpactHUD(ctx,sim,director,canvas.clientWidth<540);
}
let last=performance.now(),lastDraw=0;function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!document.hidden){update(dt);if(now-lastDraw>=1000/preferences.renderRate-1){draw();if(modal.open&&$('#workshopScene')&&!$('#workshopScene').closest('.workshop-scene').hidden)drawWorkshop($('#workshopScene'),equipped(),time,modalBusy,preferences.reducedMotion,state.stones.find(s=>s.uid===$('[name=founder]:checked')?.value));lastDraw=now;}}requestAnimationFrame(frame);}spawnLoot();applyPreferences(preferences);audio.setMap(map.id);renderPocket();save();requestAnimationFrame(frame);
document.addEventListener('pointerdown',()=>audio.unlock(),{capture:true});document.addEventListener('keydown',()=>audio.unlock(),{capture:true});document.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.closest('[data-audition],#throwBtn,#soundBtn'))audio.event('ui');},{capture:true});window.addEventListener('storage',e=>{if(e.key===SETTINGS_KEY){preferences=readSettings();audio.apply(preferences);document.body.classList.toggle('reduced-motion',preferences.reducedMotion);document.body.classList.toggle('no-hints',!preferences.hints);renderHeader();}});

if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function lineageContent(s){
 if(!s.lineage)return '';
 const l=s.lineage;
 return `<div class="research-note">${l.story?`<strong>${l.story.title}</strong><p>${l.story.text}</p>`:""}<b>第 ${l.generation} 代 · ${l.parents.length} 亲本谱系</b><br>${l.parents.map((p,i)=>`${String.fromCharCode(65+i)}：${p.name}`).join(' ＋ ')}<div class="lineage-grid">${l.loci.map((p,i)=>`<span>${TRAIT_NAMES[i]}<br>${String.fromCharCode(65+p.source)} 亲本 ${p.inherited} → <b>${s.genes[i]}</b> ${p.edited?'· 人工编辑':'· 自然继承'}</span>`).join('')}${l.outline?`<span>轮廓 / 第五位点<br>${String.fromCharCode(65+l.outline.source)} 亲本 ${l.outline.inherited} → <b>${l.outline.gene}</b> · ${l.outline.edited?'编辑偏移':l.outline.sectors?'轮廓片段交叉':'边界融合'}</span>`:''}</div></div>`;
}
function showDiscard(s){
 if(flightBusy())return;audio.event('plead');
 const lines=s.kind==='toast'?'我还没过期呢！再给我一个水面，我一定努力不泡软。':s.kind==='key'?'你都按过那么多次 ESC 了，这次可以不退出我们的友谊吗？':s.quantum?'你放下的是我，另一个叠加态的我还在抱着你的口袋呢。':s.lineage?'我爸妈把我交给你，是来见世面的……河岸也算世面吗？':'我可以再扁一点、再乖一点！再陪你漂一次，好不好？';
 openModal('等一下，我还有话说！','A VERY SMALL PLEA',`<div class="plea-card"><canvas id="pleaIcon" width="110" height="96"></canvas><div><b>${s.name}</b><blockquote>“${lines}”</blockquote></div></div><p class="farewell-note">放回河岸会从收藏中移除这块石头及其改造成果，已发现图鉴和全局纪录会保留。你仍然可以去寻找同类。</p><div class="button-row"><button class="primary" id="keepStone">好吧，再陪我一会儿</button><button class="danger-button" id="confirmDiscard">放回河岸，挥手告别</button></div>`);
 stoneIcon($('#pleaIcon'),s);$('#keepStone').onclick=()=>{audio.event('npc');showStone(s.uid);toast('“嘿嘿，我就知道你舍不得。”');};
 $('#confirmDiscard').onclick=()=>{discardStone(state,s.uid);sim=null;resultShown=true;audio.setFlight(false);audio.event('farewell');save();renderPocket();closeModal();setMode('explore');toast(`「${s.name}」回到河岸了。它挥了挥并不存在的小手。`);};
}
function showResetProgress(){
 if(flightBusy())return;audio.stopPreview();audio.event('plead');
 const pleas=['我保证下次多漂一下！','我可以负责把口袋压得很有安全感。','我们的相遇要不要再续一小段？','你还没听过我讲的冷笑话呢！','请把我也装进备份里，好不好？'];
 openModal('全体石头：申请继续陪伴！','THE POCKET PETITION',`<p class="modal-sub">${state.stones.length} 位口袋住民提交了联名信：</p><div class="petition-list">${state.stones.map((s,i)=>`<p><b>${s.name}</b>：“${pleas[i%pleas.length]}”</p>`).join('')||'<p>空口袋：“我虽然空空的，但也想再陪你一会儿。”</p>'}</div><p class="farewell-note">确认后清除当前收藏、改造、灵感、图鉴和纪录，重新开始并获得三块初始石头。声音与画面设置会保留。此操作不能撤销，可先导出备份。</p><label class="progress-confirm"><input id="resetAcknowledged" type="checkbox">我知道当前进度会被清空，准备重新出发。</label><div class="button-row"><button class="primary" id="keepProgress">不重置了，一块也不落下</button><button class="secondary" id="backupBeforeReset">先导出备份</button><button class="danger-button" id="confirmReset" disabled>确认重置进度</button></div>`);
 $('#keepProgress').onclick=()=>{audio.event('npc');showSettings();toast('口袋里传来整齐的：“耶！”');};$('#backupBeforeReset').onclick=exportSave;
 $('#resetAcknowledged').onchange=e=>$('#confirmReset').disabled=!e.target.checked;
 $('#confirmReset').onclick=()=>{if(!$('#resetAcknowledged').checked)return;resetProgress(state);lastThrow=null;$('#replayLast').disabled=true;state.sound=!preferences.muted;sim=null;charging=false;resultShown=true;collectionFilter='all';applyThrowSettings({pitch:-8,tilt:20,spin:35});map=MAPS[0];player={x:151,y:190};audio.setMap(map.id);audio.setFlight(false);spawnLoot();save();renderPocket();closeModal();setMode('explore');audio.event('farewell');toast('新的一天，三个老朋友又来敲门。进度已重置。');};
}
function applyThrowSettings(params){for(const key of ['pitch','tilt','spin']){$('#'+key).value=params[key];$('#'+key+'Value').textContent=params[key]+(key==='spin'?' r/s':'°');}}
function outlineContent(s){return `<div class="outline-panel"><canvas width="144" height="114" data-outline="${s.uid}" aria-label="${s.name}的实际俯视轮廓"></canvas><div><b>实际轮廓 · 第五项性状</b><p>${outlineLabel(s)}</p><small>轮廓基因 ${outlineGeneOf(s)} · ${surfaceLabel(s)}。每次入水按旋转后的边界计算浸水面积。<br>半径为标称外缘尺度；轮廓预览与物理求解使用同一边界。</small></div></div>`;}
function fillOutlinePreviews(){for(const c of $$('[data-outline]')){const s=state.stones.find(s=>s.uid===c.dataset.outline);if(s)drawOutline(c.getContext('2d'),s,c.width/2,c.height/2,42);}}
function beginThrow(record,replay){
 director.reset();isReplay=replay;sim=new (record.quantum?QuantumSkipSimulation:SkipSimulation)(record.stone,record.params,record.environment,rng(record.seed));
 const quantumContact=sim.onContact;
 sim.onContact=contact=>{director.impact(contact,sim);audio.setTimeScale(director.speed(sim,{speed:playbackSpeed,follow:following()}));quantumContact?.(contact);audio.event('impact',sim.contacts.length);};
 sim.onSkip=e=>audio.event('skip',e.skips);if(sim instanceof QuantumSkipSimulation)sim.onObservation=e=>audio.event('observe',e.outcome==='+'?1:0);
 soundFinished=false;audio.setFlight(true);audio.setFlightPaused(false);audio.setTimeScale(playbackSpeed);resultShown=false;resultAt=0;camera=0;
 $('#flightHud').classList.remove('hidden');$('#throwBtn').disabled=true;$('#replayLast').disabled=true;$('#throwText').textContent=replay?'正在回看这一漂…':'石头在旅行，等它一下…';
 $('#sceneMood').textContent=replay?'这一朵水花，值得再看一次。':record.quantum?'相位随飞行积累 · 量子水面负责观测':'看，轮廓正在与水面打招呼。';
 audio.event('throw');canvas.focus({preventScroll:true});
}
function replayLastThrow(){if(!lastThrow||flightBusy())return;if(modal.open)closeModal();setMode('throw');playbackSpeed=.25;$('#playbackSpeed').value='0.25';beginThrow(lastThrow,true);}
$('#playbackSpeed').onchange=e=>applyPreferences({...preferences,playbackSpeed:+e.target.value});

$('#replayLast').onclick=replayLastThrow;
function renderQuantumTelemetry(){
 const quantum=sim instanceof QuantumSkipSimulation;$('#quantumTelemetry').classList.toggle('hidden',!quantum);
 if(!quantum)return;
 const degrees=Math.round(sim.phase/TAU*360);$('#phaseReadout').textContent=degrees+'°';
 $('#waterPhaseReadout').textContent=Math.round(sim.water.phaseAt(sim.x)/TAU*360)+'°';
 $('#phaseTurns').textContent=(sim.flightPhase/TAU).toFixed(2)+' 圈';
 $('#observationReadout').textContent=sim.observations.length+' 次 '+(sim.observations.at(-1)?.outcome||'待观测');
 $('#phaseSwatch').style.color=`hsl(${degrees},55%,45%)`;$('#phaseSwatch').style.transform=`rotate(${-degrees+45}deg)`;
}
async function processStage(id,index){
 const label=$('#stageLabel');if(label)label.textContent=STAGE_LINES[id][index]+'…';
 if(index===1)audio.event(id==='quantum'?'observe':id,1);
 await new Promise(resolve=>setTimeout(resolve,preferences.reducedMotion?120:480));
}
function quantumResult(sim){return `<div class="quantum-ready">量子水域 · ${sim.observations.length} 次碰水观测 · 飞行共积累 ${(sim.flightPhase/TAU).toFixed(2)} 圈相位<br>+ 通道升力 +12% / 阻力 −4%，− 通道升力 −12% / 阻力 +4%。每次接触只观测一次，最后一次沉水也算。</div><div class="observation-log">${sim.observations.map(o=>`<span title="入水相对相位 ${Math.round(o.relative/TAU*360)}°">#${o.index} ${o.outcome} · P(+) ${Math.round(o.probability*100)}%</span>`).join('')}</div>`;}
